"def test_iterate(table: Table, mock_response_list, mock_records):
    with Mocker() as mock:
        mock.get(table.url, status_code=200, json=mock_response_list[0], complete_qs=True)
        for (n, resp) in enumerate(mock_response_list, 1):
            offset = resp.get('offset', None)
            if not offset:
                continue
            params = {'offset': offset}
            offset_url = Request('get', table.url, params=params).prepare().url
            mock.get(offset_url, status_code=200, json=mock_response_list[1], complete_qs=True)
        pages = []
        for page in table.iterate():
            pages.append(page)
    for (n, response) in enumerate(mock_response_list):
        assert len(pages[n]) == len(response['records'])
        for actual, expected in zip(pages[n], response['records']):
            assert actual['id'] == expected['id']
            assert actual['fields'] == expected['fields']
            assert actual['createdTime'] == '2023-01-01T00:00:00.000Z'"

"@pytest.mark.parametrize('workspace_param', ['workspace', 'workspace_id'])
@pytest.mark.parametrize('base_param', ['base', 'base_id'])
@pytest.mark.parametrize('kwargs,expected', [({}, {}), ({'index': 8}, {'targetIndex': '8'})])
def test_move_base(workspace, workspace_id, workspace_param, base, base_id, base_param, kwargs, expected, requests_mock):
    m = requests_mock.post(workspace.url + '/moveBase')

    import time
    start_time = time.time()

    workspace.move_base(locals()[base_param], locals()[workspace_param], **kwargs)

    end_time = time.time()
    elapsed_time = end_time - start_time

    assert m.call_count == 1
    assert m.request_history[-1].json() == {'baseId': base_id, 'targetWorkspaceId': workspace_id, **expected}

    # Check for the delay when 'index' is provided in the kwargs
    if 'index' in kwargs:
        assert elapsed_time >= 2, f"Expected delay of at least 2 seconds, but got {elapsed_time} seconds""

